const LOG_BUFFER_SIZE: usize = 2000;
// Service commands commonly perform a cold application build before binding
// their endpoint. Keep that work bounded without treating a normal build like
// the much shorter daemon-proxy startup check.
const SERVICE_READINESS_TIMEOUT: std::time::Duration = std::time::Duration::from_mins(5);
// The periodic sweep visits every managed project serially. Preserve its
// shorter budget so one cold or stuck project cannot defer convergence for all
// later project instances for the full foreground readiness window.
const BACKGROUND_SERVICE_READINESS_TIMEOUT: std::time::Duration =
    std::time::Duration::from_secs(30);
const AVAILABILITY_RETRY_DELAYS: [std::time::Duration; 5] = [
    std::time::Duration::from_secs(30),
    std::time::Duration::from_mins(1),
    std::time::Duration::from_mins(2),
    std::time::Duration::from_mins(4),
    std::time::Duration::from_mins(5),
];
const PROXY_READINESS_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(30);
const SERVICE_READINESS_POLL_INTERVAL: std::time::Duration = std::time::Duration::from_millis(500);
const MAX_PUBLISHER_BEGIN_OPERATIONS: usize = 256;

fn domain_target_remains_compatible(
    index: &DomainIndex,
    domain: &DomainName,
    expected: &DomainTarget,
) -> bool {
    let current = index.resolve(domain.as_str());
    match (expected, current) {
        (
            DomainTarget::Service {
                project_instance_id: expected_instance,
                service_name: None,
                ..
            },
            Some(DomainTarget::Service {
                project_instance_id: current_instance,
                ..
            }),
        ) => expected_instance == current_instance,
        (
            DomainTarget::Service {
                project_instance_id: expected_instance,
                service_name: Some(expected_service),
                ..
            },
            Some(DomainTarget::Service {
                project_instance_id: current_instance,
                service_name: Some(current_service),
                ..
            }),
        ) => expected_instance == current_instance && expected_service == current_service,
        _ => current == Some(expected),
    }
}

const fn demand_kind_code(kind: DemandKind) -> &'static str {
    match kind {
        DemandKind::ManualCli => "manual_cli",
        DemandKind::VsCodeWindow => "vs_code_window",
        DemandKind::AgentConversation => "agent_conversation",
        DemandKind::LegacyProcessAttachment => "legacy_process_attachment",
        DemandKind::StoppedPageResume => "stopped_page_resume",
    }
}

