    #[allow(clippy::too_many_arguments)]
    pub(crate) async fn build_service_status(
        instance_id: ProjectInstanceId,
        configured_name: String,
        name: String,
        domain: Option<String>,
        path: Option<PathBuf>,
        proxy_ports: (Option<u16>, Option<u16>),
        health_status: HealthStatus,
        health_source: HealthSource,
        snapshot: RuntimeSnapshot,
        service_config: Option<&ServiceConfig>,
        workspace: Option<String>,
        constellation: Option<String>,
        warnings: Vec<String>,
    ) -> ServiceStatus {
        use locald_core::ipc::ServiceType;

        let (status, pid, port) = match snapshot {
            RuntimeSnapshot::Static {
                is_running,
                pid,
                port,
            } => (
                if is_running {
                    locald_core::state::ServiceState::Running
                } else {
                    locald_core::state::ServiceState::Stopped
                },
                pid,
                port,
            ),
            RuntimeSnapshot::Controller(c) => {
                let state = c.lock().await.read_state().await;
                (state.status, state.pid, state.port)
            }
        };

        // Determine service type from config
        let service_type = service_config.map(ServiceType::from).unwrap_or_default();

        // Owned routed domains remain meaningful while a service is stopped:
        // the proxy still serves locald's stopped/paused surface there. Raw
        // localhost URLs remain live-runtime diagnostics.
        let url = if matches!(service_type, ServiceType::Postgres | ServiceType::Worker) {
            None
        } else if let Some(domain) = domain.as_ref() {
            let (proxy_http, proxy_https) = proxy_ports;
            if let Some(port) = proxy_https {
                if port == 443 {
                    Some(format!("https://{domain}"))
                } else {
                    Some(format!("https://{domain}:{port}"))
                }
            } else if let Some(port) = proxy_http {
                if port == 80 {
                    Some(format!("http://{domain}"))
                } else {
                    Some(format!("http://{domain}:{port}"))
                }
            } else {
                Some(format!("https://{domain}"))
            }
        } else if status == locald_core::state::ServiceState::Running {
            port.map(|port| format!("http://localhost:{port}"))
        } else {
            None
        };

        // Compute the connection URL (raw connection string)
        let connection_url = if status == locald_core::state::ServiceState::Running {
            match service_config {
                Some(ServiceConfig::Typed(TypedServiceConfig::Postgres(_))) => {
                    port.map(|p| format!("postgres://postgres@localhost:{p}/postgres"))
                }
                _ => port.map(|p| format!("http://localhost:{p}")),
            }
        } else {
            None
        };

        ServiceStatus {
            name: name.clone(),
            instance_id: Some(instance_id),
            service_name: Some(configured_name),
            service_type,
            pid,
            port,
            status,
            url,
            connection_url,
            health_status,
            health_source,
            path,
            domain,
            workspace,
            constellation,
            warnings,
            publication: None,
        }
    }

    async fn published_service_status(
        &self,
        record: &locald_core::catalog::ProjectInstanceRecord,
        declaration: &PublishedServiceDeclaration,
    ) -> ServiceStatus {
        self.published_service_status_with_state(record, declaration, None)
            .await
    }

    async fn published_service_status_with_state(
        &self,
        record: &locald_core::catalog::ProjectInstanceRecord,
        declaration: &PublishedServiceDeclaration,
        exact_state: Option<PublicationState>,
    ) -> ServiceStatus {
        use locald_core::ipc::ServiceType;

        let (publication_state, explanation, next_step) = if record.presence
            == CatalogPresence::Missing
        {
            Self::published_state_guidance(PublicationState::InstanceMissing)
        } else if let Some(exact_state) = exact_state {
            // Domain routing obtained this state atomically with its optional
            // request-scoped route. Reopening durable availability here would
            // add per-request filesystem I/O and could only make the exact
            // authority result stale.
            Self::published_state_guidance(exact_state)
        } else {
            let paused = match self.load_availability(record.id).await {
                Ok(mut availability) => availability
                    .snapshot()
                    .await
                    .map(|availability| availability.is_paused()),
                Err(error) => Err(error),
            };
            match paused {
                Ok(true) => Self::published_state_guidance(PublicationState::RoutePaused),
                Ok(false) => {
                    let key = ServiceKey::new(
                        record.id,
                        ServiceName::new(declaration.service_name.as_str()),
                    );
                    let projection = self.publisher_authority.projection(&key).await;
                    match projection {
                        Ok(Some((state, _))) => Self::published_state_guidance(state),
                        Ok(None) => {
                            Self::published_state_guidance(PublicationState::WaitingForPublisher)
                        }
                        Err(error) => {
                            warn!(
                                "failed to read publication authority for service {} in instance {}: {error}",
                                declaration.service_name, declaration.project_instance_id
                            );
                            (
                                    PublicationState::WaitingForPublisher,
                                    "The stable service identity is declared, but locald could not verify its publisher authority."
                                        .to_owned(),
                                    Some(
                                        "Inspect locald status, then retry from the owning workflow."
                                            .to_owned(),
                                    ),
                                )
                        }
                    }
                }
                Err(error) => {
                    warn!(
                        "failed to read availability while projecting published service {} in instance {}: {error}",
                        declaration.service_name, declaration.project_instance_id
                    );
                    (
                            PublicationState::WaitingForPublisher,
                            "The stable service identity is declared, but locald could not verify its lifecycle state."
                                .to_owned(),
                            Some(
                                "Inspect project status, then start the service with its owning workflow."
                                    .to_owned(),
                            ),
                        )
                }
            }
        };
        let origin = declaration.origin.to_string();
        let domain = declaration
            .origin
            .domain()
            .ok()
            .map(|domain| domain.to_string());
        let project_name = record.display_name.as_deref();
        let configured_name = declaration.service_name.as_str().to_owned();
        let name = project_name.map_or_else(
            || configured_name.clone(),
            |project_name| format!("{project_name}:{configured_name}"),
        );

        ServiceStatus {
            name,
            instance_id: Some(record.id),
            service_name: Some(configured_name),
            service_type: ServiceType::Published,
            pid: None,
            port: None,
            status: ServiceState::ExternallyManaged,
            url: Some(origin.clone()),
            connection_url: None,
            domain,
            health_status: match publication_state {
                PublicationState::CheckingEndpoint | PublicationState::RoutePaused => {
                    HealthStatus::Starting
                }
                PublicationState::EndpointUnhealthy => HealthStatus::Unhealthy,
                PublicationState::Ready => HealthStatus::Healthy,
                PublicationState::WaitingForPublisher | PublicationState::InstanceMissing => {
                    HealthStatus::Unknown
                }
            },
            health_source: HealthSource::Http,
            path: record
                .current_path
                .clone()
                .or_else(|| Some(record.last_known_path.clone())),
            workspace: None,
            constellation: None,
            warnings: Vec::new(),
            publication: Some(PublicationStatus {
                state: publication_state,
                origin,
                explanation,
                next_step,
            }),
        }
    }

    fn published_state_guidance(
        state: PublicationState,
    ) -> (PublicationState, String, Option<String>) {
        let (explanation, next_step) = match state {
            PublicationState::WaitingForPublisher => (
                "The stable service identity is declared, but no external publisher currently fulfills it.",
                Some("Start the service with its owning workflow."),
            ),
            PublicationState::CheckingEndpoint => (
                "The owning workflow has published an exact endpoint, but locald has not authorized it for routing yet.",
                Some("Wait for locald to verify the published endpoint."),
            ),
            PublicationState::EndpointUnhealthy => (
                "The owning workflow is publishing this service, but its exact endpoint is unhealthy.",
                Some("Inspect the owning workflow and its `/api/health` endpoint."),
            ),
            PublicationState::Ready => (
                "The owning workflow is publishing a healthy endpoint through this stable origin.",
                None,
            ),
            PublicationState::RoutePaused => (
                "The project route is paused; locald is preserving this published origin without routing it.",
                Some("Resume the project to allow its owning workflow to restore publication."),
            ),
            PublicationState::InstanceMissing => (
                "The worktree for this published service is missing; locald is preserving its stable origin without routing it.",
                Some(
                    "Restore the worktree, or explicitly forget the project if this identity is no longer needed.",
                ),
            ),
        };
        (state, explanation.to_owned(), next_step.map(str::to_owned))
    }

    pub async fn set_http_port(&self, port: Option<u16>) {
        self.proxy_ports.lock().await.0 = port;
        self.proxy_ports_changed.notify_waiters();
    }

    pub async fn set_https_port(&self, port: Option<u16>) {
        self.proxy_ports.lock().await.1 = port;
        self.proxy_ports_changed.notify_waiters();
    }

    pub(crate) async fn validate_published_origins_for_https_listener(
        &self,
        advertised_https_port: Option<u16>,
    ) -> Result<()> {
        let registry = self.registry.lock().await;
        match advertised_https_port {
            Some(port) => registry
                .validate_published_origins_for_https_port(port)
                .context(
                    "durable published-service origins do not match this daemon's HTTPS listener",
                ),
            None => {
                anyhow::ensure!(
                    registry.published_declarations().next().is_none(),
                    "durable published-service origins require a working HTTPS listener; repair sandbox CA material and explicitly re-admit each published project configuration"
                );
                Ok(())
            }
        }
    }

