    #[tokio::test]
    async fn status_projects_semantic_availability_without_private_owner_identity() {
        let dir = tempdir().expect("create temporary directory");
        let project_path = dir.path().join("semantic-status-project");
        let clock = FakeAvailabilityClock::new(TEST_AVAILABILITY_START_SECONDS);
        let (mut manager, instance_id, availability_data_dir) = availability_manager_with_clock(
            dir.path(),
            &project_path,
            "semantic-status",
            SharedAvailabilityClock::new(clock.clone()),
        )
        .await;
        manager.factories.insert(
            0,
            Arc::new(RetryPrepareFactory {
                failure_consumed: Arc::new(AtomicBool::new(true)),
                stop_count: Arc::new(AtomicUsize::new(0)),
            }),
        );
        write_availability_worker_config(
            &project_path,
            "semantic-status",
            "semantic-status.localhost",
            &["web"],
        );
        let private_owner = "private-conversation-identity";
        let demand = DemandKey::agent_conversation(private_owner).expect("construct agent demand");

        let idle_status = manager
            .project_status(&project_path)
            .await
            .expect("inspect project without availability state");
        let idle_list_entry = manager
            .project_list(Some(ProjectFilter::All))
            .await
            .expect("list project without availability state")
            .into_iter()
            .find(|entry| entry.project_path == idle_status.project_path)
            .expect("idle project remains listed");
        let idle_status_availability = idle_status
            .availability
            .expect("single-project status explains missing availability state");
        let idle_list_availability = idle_list_entry
            .availability
            .expect("project list explains missing availability state");
        assert_eq!(idle_list_availability, idle_status_availability);
        assert!(
            idle_list_availability
                .reasons
                .iter()
                .any(|reason| reason.code == "no_availability_state")
        );

        manager
            .project_ensure_availability(&project_path, demand.clone())
            .await
            .expect("ensure semantic-status project");
        let ready = manager
            .project_status(&project_path)
            .await
            .expect("inspect ready project");
        let ready_availability = ready.availability.as_ref().expect("availability status");
        assert_eq!(ready_availability.state, ProjectLifecycleState::Ready);
        assert!(ready_availability.desired);
        assert!(!ready_availability.always_on);
        assert!(!ready_availability.paused);
        assert_eq!(ready_availability.demands.len(), 1);
        assert_eq!(
            ready_availability.demands[0].kind,
            DemandKind::AgentConversation
        );
        assert_eq!(
            ready_availability.demands[0].safe_label,
            "Agent conversation"
        );
        assert_eq!(
            ready_availability.next_transition_at,
            Some(clock.time() + locald_core::AGENT_DEMAND_TTL)
        );
        assert!(
            !serde_json::to_string(&ready_availability)
                .expect("serialize availability status")
                .contains(private_owner)
        );
        assert_eq!(
            manager
                .project_list(Some(ProjectFilter::Active))
                .await
                .expect("list active projects")
                .into_iter()
                .map(|entry| entry.project_path)
                .collect::<Vec<_>>(),
            vec![std::fs::canonicalize(&project_path).expect("canonical project path")]
        );

        manager
            .stop("semantic-status:web")
            .await
            .expect("stop one service without changing project availability");
        let degraded = manager
            .project_status(&project_path)
            .await
            .expect("inspect service-level override");
        assert_eq!(
            degraded.service_details[0].service_type,
            locald_core::ipc::ServiceType::Worker
        );
        // Portless workers never have routed URLs. Routable services preserve
        // their semantic domains while stopped so the proxy can explain state.
        assert_eq!(degraded.service_details[0].url, None);
        let degraded_availability = degraded.availability.expect("degraded availability status");
        assert_eq!(degraded_availability.state, ProjectLifecycleState::Degraded);
        assert!(degraded_availability.desired);
        assert!(
            degraded_availability
                .reasons
                .iter()
                .any(|reason| reason.code == "service_override")
        );

        manager
            .project_pause_availability(&project_path)
            .await
            .expect("pause project");
        assert!(
            manager
                .project_renew_availability(&project_path, &demand)
                .await
                .expect("passively renew paused owner")
        );
        let paused = manager
            .project_status(&project_path)
            .await
            .expect("inspect paused project");
        let paused_availability = paused.availability.expect("paused availability status");
        assert_eq!(paused_availability.state, ProjectLifecycleState::Paused);
        assert!(!paused_availability.desired);
        assert!(paused_availability.paused);
        assert!(
            paused_availability.demands.is_empty(),
            "a pre-pause lease remains durable but is not an effective owner"
        );
        assert_eq!(paused_availability.next_transition_at, None);
        assert!(!paused.is_running);
        assert_eq!(paused.service_details[0].url, None);

        let editor_demand =
            DemandKey::vs_code_window("active-window").expect("construct editor demand");
        manager
            .project_ensure_availability(&project_path, editor_demand.clone())
            .await
            .expect("resume project through a new editor generation");
        let resumed = manager
            .project_status(&project_path)
            .await
            .expect("inspect editor-resumed project")
            .availability
            .expect("editor-resumed availability status");
        assert_eq!(resumed.state, ProjectLifecycleState::Ready);
        assert!(resumed.desired);
        assert!(!resumed.paused);
        assert_eq!(resumed.demands.len(), 1);
        assert_eq!(resumed.demands[0].kind, DemandKind::VsCodeWindow);
        assert_eq!(
            resumed.next_transition_at,
            Some(clock.time() + locald_core::VSCODE_DEMAND_TTL),
            "the effective editor owner, not the older suppressed owner, controls the next transition"
        );
        assert!(resumed.reasons.iter().any(|reason| {
            reason.code == "demand_agent_conversation"
                && reason.message == "Agent conversation demand remains live behind the last pause."
        }));
        assert!(resumed.reasons.iter().any(|reason| {
            reason.code == "demand_vs_code_window"
                && reason.message == "VS Code window demand is active."
        }));

        let mut availability = AvailabilityStore::load_with_clock(
            &availability_data_dir,
            instance_id,
            SharedAvailabilityClock::new(clock.clone()),
        )
        .await
        .expect("reload semantic-status availability");
        assert!(
            availability
                .release_demand(&editor_demand)
                .await
                .expect("release editor demand")
        );
        assert_eq!(
            manager
                .converge_project_availability(&project_path)
                .await
                .expect("enter cooldown after the effective owner releases"),
            Some(ConvergenceDecision::PreserveRuntimeUntil {
                deadline: clock.time() + locald_core::SHUTDOWN_COOLDOWN,
            })
        );

        manager
            .project_set_always_on(&project_path, true)
            .await
            .expect("resume project with Always On");
        let always_on = manager
            .project_status(&project_path)
            .await
            .expect("inspect Always On project");
        let always_on_availability = always_on
            .availability
            .expect("Always On availability status");
        assert_eq!(always_on_availability.state, ProjectLifecycleState::Ready);
        assert!(always_on_availability.desired);
        assert!(always_on_availability.always_on);
        assert!(!always_on_availability.paused);
        assert!(
            always_on_availability.demands.is_empty(),
            "Always On is the effective policy; the older lease remains suppressed"
        );
        assert_eq!(always_on_availability.next_transition_at, None);
        assert!(
            always_on_availability.reasons.iter().any(|reason| {
                reason.code == "demand_agent_conversation"
                    && reason.message
                        == "Agent conversation demand remains live behind the last pause."
            }),
            "resuming through Always On must not describe an older suppressed owner as active"
        );
        assert!(manager.project_runtime_is_ready(instance_id).await);

        manager
            .project_set_always_on(&project_path, false)
            .await
            .expect("disable Always On");
        clock.advance(locald_core::SHUTDOWN_COOLDOWN);
        assert_eq!(
            manager
                .converge_project_availability(&project_path)
                .await
                .expect("finish shutdown after Always On is disabled"),
            Some(ConvergenceDecision::EnsureDown)
        );
        let stopped = manager
            .project_status(&project_path)
            .await
            .expect("inspect stopped project with an older live demand")
            .availability
            .expect("stopped availability status");
        assert_eq!(stopped.state, ProjectLifecycleState::Stopped);
        assert!(!stopped.desired);
        assert!(!stopped.paused);
        assert!(
            stopped.demands.is_empty(),
            "suppressed leases are retained internally, not projected as active owners"
        );
        assert!(
            stopped
                .reasons
                .iter()
                .any(|reason| reason.code == "no_live_demand")
        );
        assert!(stopped.reasons.iter().any(|reason| {
            reason.code == "demand_agent_conversation"
                && reason.message == "Agent conversation demand remains live behind the last pause."
        }));
    }

