    #[test]
    fn persistent_worktree_slugs_qualify_exact_service_domains() {
        let config: LocaldConfig = toml::from_str(
            r#"
[project]
name = "app"
domain = "app.localhost"

[worktrees]
domain = "{{branch.last}}.{{project.domain}}"

[services.web]
command = "web"

[services.api]
command = "api"
"#,
        )
        .expect("parse compatibility config");

        let main_claims = ProcessManager::build_domain_claims(test_instance_id(), &config, None)
            .expect("primary checkout claims");
        let main_domains = main_claims
            .into_iter()
            .map(|claim| claim.domain.to_string())
            .collect::<HashSet<_>>();
        assert_eq!(
            main_domains,
            HashSet::from(["app.localhost".to_owned(), "api.app.localhost".to_owned(),])
        );

        let worktree_claims =
            ProcessManager::build_domain_claims(test_instance_id(), &config, Some("turn-trace"))
                .expect("linked worktree claims");
        let worktree_domains = worktree_claims
            .into_iter()
            .map(|claim| claim.domain.to_string())
            .collect::<HashSet<_>>();
        assert_eq!(
            worktree_domains,
            HashSet::from([
                "turn-trace.on.app.localhost".to_owned(),
                "api.turn-trace.on.app.localhost".to_owned(),
            ])
        );

        let error =
            ProcessManager::build_domain_claims(test_instance_id(), &config, Some("bad_slug"))
                .expect_err("invalid persisted slugs remain strict");
        assert!(
            error
                .to_string()
                .contains("invalid persistent worktree slug")
        );
    }

    #[test]
    fn explicit_service_domains_are_relative_to_the_instance_namespace() {
        let config: LocaldConfig = toml::from_str(
            r#"
[project]
name = "v0"
domain = "v0.localhost"

[services.web]
command = "web"
domains = ["@"]

[services.frame]
command = "frame"
domains = ["frame", "*.frame", "frame-alias"]

[services.internal]
command = "internal"
domains = []
"#,
        )
        .expect("parse explicit service domains");

        let claims =
            ProcessManager::build_domain_claims(test_instance_id(), &config, Some("turn-trace"))
                .expect("build namespaced claims");
        let claims = claims
            .into_iter()
            .map(|claim| {
                let primary = matches!(claim.target, DomainTarget::Service { primary: true, .. });
                (claim.domain.to_string(), primary)
            })
            .collect::<BTreeMap<_, _>>();

        assert_eq!(
            claims,
            BTreeMap::from([
                ("frame-alias.turn-trace.on.v0.localhost".to_owned(), false,),
                ("frame.turn-trace.on.v0.localhost".to_owned(), true),
                ("turn-trace.on.v0.localhost".to_owned(), true),
                ("*.frame.turn-trace.on.v0.localhost".to_owned(), false),
            ])
        );
    }

