    #[tokio::test]
    async fn test_url_generation_clean_ports() {
        let name = "test".to_string();
        let path = None;
        let health_status = locald_core::state::HealthStatus::Healthy;
        let health_source = locald_core::state::HealthSource::None;

        // Helper to create a running snapshot
        let running_snapshot = || RuntimeSnapshot::Static {
            is_running: true,
            pid: Some(123),
            port: Some(3000),
        };

        // Case 1: HTTP on port 80 -> No port in URL
        let status = ProcessManager::build_service_status(
            test_instance_id(),
            name.clone(),
            name.clone(),
            Some("app.test".to_string()),
            path.clone(),
            (Some(80), None), // HTTP=80, HTTPS=None
            health_status,
            health_source,
            running_snapshot(),
            None,
            None,
            None,
            Vec::new(),
        )
        .await;
        assert_eq!(status.url, Some("http://app.test".to_string()));

        // Case 2: HTTPS on port 443 -> No port in URL
        let status = ProcessManager::build_service_status(
            test_instance_id(),
            name.clone(),
            name.clone(),
            Some("app.test".to_string()),
            path.clone(),
            (Some(80), Some(443)), // HTTP=80, HTTPS=443
            health_status,
            health_source,
            running_snapshot(),
            None,
            None,
            None,
            Vec::new(),
        )
        .await;
        assert_eq!(status.url, Some("https://app.test".to_string()));

        // Case 3: HTTP on non-standard port -> Port in URL
        let status = ProcessManager::build_service_status(
            test_instance_id(),
            name.clone(),
            name.clone(),
            Some("app.test".to_string()),
            path.clone(),
            (Some(8080), None),
            health_status,
            health_source,
            running_snapshot(),
            None,
            None,
            None,
            Vec::new(),
        )
        .await;
        assert_eq!(status.url, Some("http://app.test:8080".to_string()));

        // Case 4: HTTPS on non-standard port -> Port in URL
        let status = ProcessManager::build_service_status(
            test_instance_id(),
            name.clone(),
            name.clone(),
            Some("app.test".to_string()),
            path.clone(),
            (None, Some(8443)),
            health_status,
            health_source,
            running_snapshot(),
            None,
            None,
            None,
            Vec::new(),
        )
        .await;
        assert_eq!(status.url, Some("https://app.test:8443".to_string()));

        // Case 5: Privileged ports (80/443). URLs should NOT contain port numbers.
        let status = ProcessManager::build_service_status(
            test_instance_id(),
            name.clone(),
            name.clone(),
            Some("myapp.localhost".to_string()),
            path.clone(),
            (Some(80), Some(443)),
            health_status,
            health_source,
            running_snapshot(),
            None,
            None,
            None,
            Vec::new(),
        )
        .await;
        assert_eq!(status.url, Some("https://myapp.localhost".to_string()));
        // Verify no high port leaks into URLs
        assert!(!status.url.as_deref().unwrap_or("").contains("8443"));
        assert!(!status.url.as_deref().unwrap_or("").contains("8080"));

        // Portless workers never advertise a routed domain, even when the
        // project owns one and the runtime snapshot contains stale port data.
        let worker_config = ServiceConfig::Typed(TypedServiceConfig::Worker(
            locald_core::config::WorkerServiceConfig::default(),
        ));
        let status = ProcessManager::build_service_status(
            test_instance_id(),
            "worker".to_owned(),
            "worker".to_owned(),
            Some("worker.app.test".to_owned()),
            path,
            (Some(80), Some(443)),
            health_status,
            health_source,
            running_snapshot(),
            Some(&worker_config),
            None,
            None,
            Vec::new(),
        )
        .await;
        assert_eq!(status.service_type, locald_core::ipc::ServiceType::Worker);
        assert_eq!(status.url, None);
    }

    #[test]
    fn test_log_buffer_capacity() {
        let mut buffer = LogBuffer::new(3);
        let entry = LogEntry {
            service: "test".to_string(),
            instance_id: None,
            service_name: None,
            service_domain: None,
            message: "msg".to_string(),
            stream: locald_core::ipc::LogStream::Stdout,
            timestamp: 0,
        };

        buffer.push(entry.clone());
        buffer.push(entry.clone());
        buffer.push(entry.clone());
        assert_eq!(buffer.get_all().len(), 3);

        buffer.push(entry.clone());
        assert_eq!(buffer.get_all().len(), 3);
    }

    #[test]
    fn test_log_buffer_fifo() {
        let mut buffer = LogBuffer::new(2);
        let entry1 = LogEntry {
            service: "test".to_string(),
            instance_id: None,
            service_name: None,
            service_domain: None,
            message: "1".to_string(),
            stream: locald_core::ipc::LogStream::Stdout,
            timestamp: 1,
        };
        let entry2 = LogEntry {
            service: "test".to_string(),
            instance_id: None,
            service_name: None,
            service_domain: None,
            message: "2".to_string(),
            stream: locald_core::ipc::LogStream::Stdout,
            timestamp: 2,
        };
        let entry3 = LogEntry {
            service: "test".to_string(),
            instance_id: None,
            service_name: None,
            service_domain: None,
            message: "3".to_string(),
            stream: locald_core::ipc::LogStream::Stdout,
            timestamp: 3,
        };

        buffer.push(entry1.clone());
        buffer.push(entry2.clone());

        let logs = buffer.get_all();
        assert_eq!(logs[0].message, "1");
        assert_eq!(logs[1].message, "2");

        buffer.push(entry3.clone());

        let logs = buffer.get_all();
        assert_eq!(logs.len(), 2);
        assert_eq!(logs[0].message, "2");
        assert_eq!(logs[1].message, "3");
    }

