    #[tokio::test]
    async fn published_only_pause_and_resume_invalidate_service_projection() {
        let directory = tempdir().expect("create published lifecycle fixture");
        let project_path = directory.path().join("project");
        std::fs::create_dir(&project_path).expect("create published lifecycle project");
        std::fs::write(
            project_path.join("locald.toml"),
            r#"
[project]
name = "published-lifecycle"
domain = "published-lifecycle.localhost"

[services.workbench]
type = "published"
domains = ["workbench"]
"#,
        )
        .expect("write published lifecycle config");
        let mut manager = ProcessManager::new(
            directory.path().join("notify.sock"),
            Arc::new(StateManager::with_path(directory.path().join("state.json"))),
            Arc::new(Mutex::new(Registry::with_path(
                directory.path().join("catalog.json"),
            ))),
            Arc::new(Mutex::new(AttachmentStore::new(
                directory.path().join("attachments.json"),
            ))),
            None,
        )
        .expect("create published lifecycle manager");
        manager.use_sandbox_host_set_writer();
        manager.set_https_port(Some(4443)).await;
        manager
            .apply_config(project_path.clone(), None, false)
            .await
            .expect("admit published lifecycle declaration");
        let demand = DemandKey::manual_cli();
        manager
            .project_ensure_availability(&project_path, demand.clone())
            .await
            .expect("establish initial published availability");

        let (instance_id, _) = manager
            .required_availability_instance_for_path(&project_path)
            .await
            .expect("resolve published lifecycle instance");
        insert_buffered_test_log(&manager, instance_id, "workbench", "pause history");
        let authority = manager.publisher_authority();
        let principal =
            PublisherPrincipal::new(501, 42, crate::publication::PublisherProcessBirth::Test(1));
        let preparation = authority
            .reserve_acquisition(
                ServiceKey::new(instance_id, ServiceName::new("workbench")),
                principal.clone(),
                None,
            )
            .await
            .expect("reserve published lifecycle acquisition");
        let PublisherAcquisitionPreparation::Required(permit) = preparation else {
            panic!("fresh publication requires preparation");
        };
        let prepared = authority
            .complete_acquisition_preparation(permit)
            .await
            .expect("complete published lifecycle preparation");
        let acquired = manager
            .acquire_published_endpoint(
                prepared.acquisition_attempt_handle(),
                &principal,
                prepared.origin(),
                RetainedListenerCapability::new(
                    crate::publication::ListenerIdentity::Test(1),
                    Arc::new(()),
                ),
            )
            .await
            .expect("acquire published lifecycle lease");
        assert_eq!(
            acquired.publication_state(),
            publisher_protocol::PublicationState::CheckingEndpoint
        );

        let mut events = manager.event_sender.subscribe();
        assert!(
            manager
                .project_pause_availability(&project_path)
                .await
                .expect("pause published route")
        );
        assert_eq!(
            tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, events.recv())
                .await
                .expect("pause invalidation arrives within the test boundary")
                .expect("receive pause invalidation"),
            Event::ServiceListChanged
        );
        assert!(matches!(
            events.try_recv(),
            Err(tokio::sync::broadcast::error::TryRecvError::Empty)
        ));
        let paused = manager
            .list()
            .await
            .into_iter()
            .find(|status| status.name == "published-lifecycle:workbench")
            .expect("paused published status remains visible");
        assert_eq!(
            paused
                .publication
                .as_ref()
                .map(|publication| publication.state),
            Some(PublicationState::RoutePaused)
        );
        let renewed_while_paused = manager
            .renew_published_endpoint(acquired.lease_handle(), &principal)
            .await
            .expect("passive publisher renewal remains authorized while paused");
        assert_eq!(
            renewed_while_paused.publication_state(),
            publisher_protocol::PublicationState::RoutePaused
        );
        // An idempotent lifecycle retry must repair endpoint authority if a
        // prior durable pause committed immediately before a wake barrier.
        authority
            .set_project_paused(instance_id, false)
            .await
            .expect("inject stale endpoint pause projection");
        assert!(
            !manager
                .publish_publisher_pause_transition(instance_id, true, true)
                .await
                .expect("idempotent pause repairs endpoint authority")
        );
        assert_eq!(
            manager
                .renew_published_endpoint(acquired.lease_handle(), &principal)
                .await
                .expect("repaired pause remains passively renewable")
                .publication_state(),
            publisher_protocol::PublicationState::RoutePaused
        );
        let wait_error = authority
            .wait_ready(
                acquired.lease_handle(),
                &principal,
                acquired.binding_revision(),
            )
            .await
            .expect_err("a paused route cannot become ready");
        assert_eq!(
            wait_error.code(),
            publisher_protocol::StableErrorCode::ProjectPaused
        );

        assert!(
            !manager
                .project_pause_availability(&project_path)
                .await
                .expect("repeating pause is a no-op")
        );
        assert!(
            manager
                .project_renew_availability(&project_path, &demand)
                .await
                .expect("passively renew the suppressed demand")
        );
        assert!(matches!(
            events.try_recv(),
            Err(tokio::sync::broadcast::error::TryRecvError::Empty)
        ));

        manager
            .project_ensure_availability(&project_path, demand.clone())
            .await
            .expect("semantic activity resumes the published route");
        assert_eq!(
            tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, events.recv())
                .await
                .expect("resume invalidation arrives within the test boundary")
                .expect("receive resume invalidation"),
            Event::ServiceListChanged
        );
        assert!(matches!(
            events.try_recv(),
            Err(tokio::sync::broadcast::error::TryRecvError::Empty)
        ));
        let resumed = manager
            .list()
            .await
            .into_iter()
            .find(|status| status.name == "published-lifecycle:workbench")
            .expect("resumed published status remains visible");
        assert_eq!(
            resumed
                .publication
                .as_ref()
                .map(|publication| publication.state),
            Some(PublicationState::CheckingEndpoint)
        );
        let renewed_after_resume = manager
            .renew_published_endpoint(acquired.lease_handle(), &principal)
            .await
            .expect("publisher lease remains live after resume");
        assert_eq!(
            renewed_after_resume.publication_state(),
            publisher_protocol::PublicationState::CheckingEndpoint
        );
        assert_eq!(
            manager.get_recent_logs_for_instance(Some(instance_id))[0].message,
            "pause history"
        );

        manager
            .project_ensure_availability(&project_path, demand)
            .await
            .expect("a live semantic demand renews without a projection change");
        assert!(matches!(
            events.try_recv(),
            Err(tokio::sync::broadcast::error::TryRecvError::Empty)
        ));

        assert!(
            manager
                .project_pause_availability(&project_path)
                .await
                .expect("pause the published route before enabling Always On")
        );
        assert_eq!(
            tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, events.recv())
                .await
                .expect("second pause invalidation arrives within the test boundary")
                .expect("receive second pause invalidation"),
            Event::ServiceListChanged
        );
        manager
            .project_set_always_on(&project_path, true)
            .await
            .expect("Always On resumes a paused published route transactionally");
        assert_eq!(
            tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, events.recv())
                .await
                .expect("Always On invalidation arrives within the test boundary")
                .expect("receive Always On invalidation"),
            Event::ServiceListChanged
        );
        assert!(matches!(
            events.try_recv(),
            Err(tokio::sync::broadcast::error::TryRecvError::Empty)
        ));
    }

