    #[tokio::test]
    async fn ensure_project_registers_then_returns_ready_semantic_urls() {
        let dir = tempdir().expect("create EnsureProject directory");
        let project_path = dir.path().join("ensure-project");
        std::fs::create_dir(&project_path).expect("create EnsureProject project");
        std::fs::write(
            project_path.join("locald.toml"),
            r#"
[project]
name = "ensure-project"
domain = "ensure-project.localhost"

[services.web]
command = "unused-by-test-factory"
health_check = "true"

[services.web.env]
PATH = "/usr/bin:/bin"
"#,
        )
        .expect("write EnsureProject config");
        let mut manager = unregistered_availability_manager(dir.path());
        let creates = Arc::new(AtomicUsize::new(1));
        manager.factories.insert(
            0,
            Arc::new(RetryingReadinessFactory {
                creates: creates.clone(),
                stops: Arc::new(AtomicUsize::new(0)),
            }),
        );

        let unrelated_file = project_path.join("README.md");
        std::fs::write(&unrelated_file, "not a locald project locator")
            .expect("write unrelated file locator");
        let unrelated_file_error = manager
            .ensure_project(unrelated_file, DemandKey::manual_cli())
            .await
            .expect_err("unrelated file locator is rejected");
        assert!(
            format!("{unrelated_file_error:#}")
                .contains("file other than `locald.toml` or `Procfile`")
        );
        assert!(manager.registry.lock().await.instances.is_empty());

        let malformed_demand: DemandKey = serde_json::from_value(serde_json::json!({
            "kind": "agent_conversation",
            "owner": "not-a-canonical-digest"
        }))
        .expect("deserialize malformed demand fixture");
        let malformed_error = manager
            .ensure_project(project_path.clone(), malformed_demand)
            .await
            .expect_err("malformed demand is rejected before registration");
        assert!(format!("{malformed_error:#}").contains("invalid EnsureProject demand"));
        assert!(manager.registry.lock().await.instances.is_empty());

        let legacy_error = manager
            .ensure_project(
                project_path.clone(),
                DemandKey::legacy_process_attachment("untrusted-pid")
                    .expect("construct compatibility demand"),
            )
            .await
            .expect_err("semantic ensure rejects compatibility ownership");
        assert!(
            format!("{legacy_error:#}")
                .contains("does not accept legacy process-attachment demands")
        );
        assert!(manager.registry.lock().await.instances.is_empty());

        let (event_tx, mut event_rx) = tokio::sync::mpsc::channel(100);
        let mut ensure = tokio::spawn({
            let manager = manager.clone();
            let config_path = project_path.join("locald.toml");
            async move {
                manager
                    .ensure_project_from_ipc_with_events(
                        config_path,
                        DemandKey::manual_cli(),
                        None,
                        event_tx,
                    )
                    .await
            }
        });
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(50), &mut ensure)
                .await
                .is_err(),
            "EnsureProject waits for the HTTPS proxy listener"
        );
        assert!(manager.registry.lock().await.instances.is_empty());
        manager.set_https_port(Some(8443)).await;

        let result = ensure
            .await
            .expect("join first project registration")
            .expect("ensure first project registration");
        assert_eq!(result.state, EnsureProjectState::Ready);
        assert_eq!(
            result.project_path,
            std::fs::canonicalize(&project_path).expect("canonical EnsureProject path")
        );
        assert_eq!(result.project_name.as_deref(), Some("ensure-project"));
        assert_eq!(result.urls, vec!["https://ensure-project.localhost:8443"]);
        assert_eq!(result.services.len(), 1);
        assert_eq!(result.services[0].name, "ensure-project:web");
        assert_eq!(result.services[0].status, ServiceState::Running);
        assert_eq!(result.services[0].health_status, HealthStatus::Healthy);
        assert_eq!(
            result.services[0].url.as_deref(),
            Some("https://ensure-project.localhost:8443")
        );
        assert!(
            event_rx.try_recv().is_ok(),
            "verbose EnsureProject streams boot progress before readiness"
        );
        assert_eq!(creates.load(Ordering::SeqCst), 2);

        let (instance_id, _) = manager
            .required_availability_instance_for_path(&project_path)
            .await
            .expect("resolve newly registered EnsureProject instance");
        manager
            .project_pause_availability(&project_path)
            .await
            .expect("pause ensured project");
        let stopped_domain_status = manager
            .project_availability_by_domain("ensure-project.localhost")
            .await
            .expect("resolve stopped-domain availability");
        assert_eq!(stopped_domain_status.state, ProjectLifecycleState::Paused);
        assert!(stopped_domain_status.paused);
        let platform_error = manager
            .ensure_project_for_domain("locald.localhost")
            .await
            .expect_err("platform domains cannot acquire project availability");
        assert!(
            format!("{platform_error:#}").contains("is not owned by a locald project"),
            "unexpected platform-domain error: {platform_error:#}"
        );
        let resumed_from_domain = manager
            .ensure_project_for_domain("ENSURE-PROJECT.LOCALHOST.")
            .await
            .expect("resume the exact project owner from its stopped domain");
        assert_eq!(resumed_from_domain.state, EnsureProjectState::Ready);
        assert_eq!(
            resumed_from_domain.urls,
            vec!["https://ensure-project.localhost:8443"]
        );
        let resumed_snapshot = manager
            .load_availability(instance_id)
            .await
            .expect("load domain-resumed availability")
            .snapshot()
            .await
            .expect("read domain-resumed availability");
        assert!(!resumed_snapshot.is_paused());
        assert!(
            resumed_snapshot
                .demands()
                .iter()
                .any(|lease| lease.kind() == DemandKind::StoppedPageResume),
            "domain Resume records the explicit stopped-page demand"
        );

        {
            let mut registry = manager.registry.lock().await;
            let record = registry
                .instances
                .get_mut(&instance_id)
                .expect("registered EnsureProject instance");
            record.current_path = None;
            record.presence = CatalogPresence::Missing;
            registry
                .save()
                .await
                .expect("persist missing catalog state");
        }
        let reactivated = manager
            .ensure_project(project_path.clone(), DemandKey::manual_cli())
            .await
            .expect("EnsureProject republishes a reappeared catalog instance");
        assert_eq!(reactivated.state, EnsureProjectState::Ready);
        let registry = manager.registry.lock().await;
        let reactivated_record = registry
            .instances
            .get(&instance_id)
            .expect("reactivated EnsureProject instance remains catalogued");
        assert_eq!(
            reactivated_record.current_path.as_deref(),
            Some(
                std::fs::canonicalize(&project_path)
                    .expect("canonical reactivated project")
                    .as_path()
            )
        );
        assert_eq!(reactivated_record.presence, CatalogPresence::Active);
        drop(registry);

        manager.set_https_port(Some(443)).await;
        let standard_result = manager
            .ensure_project_result(instance_id)
            .await
            .expect("project result uses standard-mode routed URL");
        assert_eq!(
            standard_result.urls,
            vec!["https://ensure-project.localhost"]
        );
        assert_eq!(
            standard_result.services[0].url.as_deref(),
            Some("https://ensure-project.localhost")
        );
        let snapshot = manager
            .load_availability(instance_id)
            .await
            .expect("load EnsureProject availability")
            .snapshot()
            .await
            .expect("read EnsureProject availability");
        assert!(
            snapshot
                .demands()
                .iter()
                .any(|lease| lease.kind() == DemandKind::ManualCli)
        );
    }

    #[tokio::test]
    async fn agent_inspect_binds_registered_project_without_creating_availability() {
        let dir = tempdir().expect("create agent inspect directory");
        let project_path = dir.path().join("agent-inspect");
        std::fs::create_dir(&project_path).expect("create agent inspect project");
        std::fs::write(
            project_path.join("locald.toml"),
            r#"
[project]
name = "agent-inspect"

[services.web]
command = "unused-by-inspect"
"#,
        )
        .expect("write agent inspect config");
        let (manager, instance_id, availability_data_dir) =
            availability_manager(dir.path(), &project_path, "agent-inspect").await;
        manager.set_https_port(Some(8443)).await;
        let domain_index = {
            let mut registry = manager.registry.lock().await;
            registry
                .replace_domain_claims(
                    instance_id,
                    [DomainClaim::service(
                        "agent-inspect.localhost"
                            .parse()
                            .expect("parse agent inspect domain"),
                        instance_id,
                        "agent-inspect:web".to_owned(),
                    )],
                )
                .expect("publish agent inspect domain");
            registry.save().await.expect("persist agent inspect domain");
            registry.domain_index().clone()
        };
        manager.domain_index.store(domain_index);
        let context = test_agent_context(&project_path, "inspect conversation");

        let status = manager
            .agent_inspect_project(&context)
            .await
            .expect("inspect registered project");

        assert_eq!(status.registration, AgentProjectRegistration::Registered);
        assert_eq!(status.project_name.as_deref(), Some("agent-inspect"));
        assert_eq!(status.services.len(), 1);
        assert_eq!(status.services[0].name, "web");
        assert_eq!(status.services[0].status, ServiceState::Stopped);
        assert_eq!(status.services[0].health_status, HealthStatus::Unknown);
        assert_eq!(
            status.services[0].url.as_deref(),
            Some("https://agent-inspect.localhost:8443")
        );
        assert_eq!(status.urls, vec!["https://agent-inspect.localhost:8443"]);
        assert_eq!(
            manager
                .registry
                .lock()
                .await
                .agent_binding(&context.conversation),
            Some(instance_id)
        );
        assert!(
            !availability_path(&availability_data_dir, instance_id).exists(),
            "observational inspect does not create availability state"
        );
        assert!(manager.services.lock().await.is_empty());
    }

    #[tokio::test]
    async fn agent_inspect_does_not_retarget_a_recreated_git_worktree_by_path() {
        let dir = tempdir().expect("create recreated worktree directory");
        let project_path = dir.path().join("recreated-agent-project");
        std::fs::create_dir(&project_path).expect("create original Git project");
        git(&project_path, &["init"]);
        std::fs::write(
            project_path.join("locald.toml"),
            "[project]\nname = \"recreated-agent-project\"\n",
        )
        .expect("write original config");
        let (manager, historical_instance, _) =
            availability_manager(dir.path(), &project_path, "recreated-agent-project").await;

        std::fs::remove_dir_all(&project_path).expect("remove original Git project");
        std::fs::create_dir(&project_path).expect("recreate Git project at old path");
        git(&project_path, &["init"]);
        std::fs::write(
            project_path.join("locald.toml"),
            "[project]\nname = \"recreated-agent-project\"\n",
        )
        .expect("write replacement config");
        let context = test_agent_context(&project_path, "replacement conversation");

        let status = manager
            .agent_inspect_project(&context)
            .await
            .expect("inspect replacement worktree");

        assert_eq!(status.registration, AgentProjectRegistration::Unregistered);
        let registry = manager.registry.lock().await;
        assert_eq!(
            registry.agent_binding(&context.conversation),
            None,
            "an unregistered physical replacement cannot inherit the old instance binding"
        );
        assert!(registry.instances.contains_key(&historical_instance));
    }

    #[tokio::test]
    async fn agent_inspect_does_not_treat_a_non_git_replacement_as_the_stale_git_instance() {
        let dir = tempdir().expect("create Git-to-non-Git replacement directory");
        let project_path = dir.path().join("agent-origin-replacement");
        std::fs::create_dir(&project_path).expect("create original Git project");
        git(&project_path, &["init"]);
        std::fs::write(
            project_path.join("locald.toml"),
            "[project]\nname = \"agent-origin-replacement\"\n",
        )
        .expect("write original config");
        let (manager, historical_instance, _) =
            availability_manager(dir.path(), &project_path, "agent-origin-replacement").await;

        std::fs::remove_dir_all(project_path.join(".git")).expect("remove Git identity");
        let unbound = test_agent_context(&project_path, "non-Git replacement conversation");
        let status = manager
            .agent_inspect_project(&unbound)
            .await
            .expect("inspect non-Git replacement");
        assert_eq!(status.registration, AgentProjectRegistration::Unregistered);
        assert_eq!(
            manager
                .registry
                .lock()
                .await
                .agent_binding(&unbound.conversation),
            None
        );

        let bound = test_agent_context(&project_path, "historical Git conversation");
        {
            let mut registry = manager.registry.lock().await;
            let mut candidate = registry.clone();
            candidate
                .bind_agent_conversation(bound.conversation.clone(), historical_instance)
                .expect("bind historical Git conversation");
            registry
                .commit_candidate(candidate)
                .await
                .expect("publish historical Git binding");
        }
        let error = manager
            .agent_inspect_project(&bound)
            .await
            .expect_err("non-Git replacement cannot inherit a Git conversation binding");
        assert!(format!("{error:#}").contains("cannot silently retarget"));
    }

