    #[tokio::test]
    async fn agent_ensure_registers_binds_renews_and_returns_only_semantic_state() {
        let dir = tempdir().expect("create agent ensure directory");
        let project_path = dir.path().join("agent-ensure");
        std::fs::create_dir(&project_path).expect("create agent ensure project");
        std::fs::write(
            project_path.join("locald.toml"),
            r#"
[project]
name = "agent-ensure"
domain = "agent-ensure.localhost"

[services.web]
command = "unused-by-test-factory"
health_check = "true"
"#,
        )
        .expect("write agent ensure config");
        let mut manager = unregistered_availability_manager(dir.path());
        manager.factories.insert(
            0,
            Arc::new(RetryingReadinessFactory {
                creates: Arc::new(AtomicUsize::new(1)),
                stops: Arc::new(AtomicUsize::new(0)),
            }),
        );
        manager.set_https_port(Some(8443)).await;
        let first = test_agent_context(&project_path, "first private conversation");

        let before = manager
            .agent_inspect_project(&first)
            .await
            .expect("inspect unregistered project");
        assert_eq!(before.registration, AgentProjectRegistration::Unregistered);
        assert!(manager.registry.lock().await.instances.is_empty());

        let status = manager
            .agent_ensure_project(&first, Some("/agent/bin:/usr/bin".to_owned()))
            .await
            .expect("ensure ambient agent project");
        assert_eq!(status.registration, AgentProjectRegistration::Registered);
        assert_eq!(status.urls, vec!["https://agent-ensure.localhost:8443"]);
        assert_eq!(status.services.len(), 1);
        assert_eq!(status.services[0].name, "web");
        assert_eq!(status.services[0].status, ServiceState::Running);
        assert_eq!(status.services[0].health_status, HealthStatus::Healthy);
        assert_eq!(
            status.services[0].url.as_deref(),
            Some("https://agent-ensure.localhost:8443")
        );

        let instance_id = manager
            .registry
            .lock()
            .await
            .agent_binding(&first.conversation)
            .expect("conversation is durably bound");
        let snapshot = manager
            .load_availability(instance_id)
            .await
            .expect("load agent availability")
            .snapshot()
            .await
            .expect("read agent availability");
        assert_eq!(snapshot.trusted_launch_path(), Some("/agent/bin:/usr/bin"));
        assert_eq!(
            snapshot
                .demands()
                .iter()
                .filter(|lease| lease.kind() == DemandKind::AgentConversation)
                .count(),
            1
        );

        let reopened = reopen_availability_manager_with_clock(
            dir.path(),
            dir.path().join("availability-data"),
            SharedAvailabilityClock::system(),
        )
        .await;
        let reopened_status = reopened
            .agent_inspect_project(&first)
            .await
            .expect("inspect the same conversation after daemon restart");
        assert_eq!(
            reopened_status.registration,
            AgentProjectRegistration::Registered
        );
        assert_eq!(
            reopened
                .registry
                .lock()
                .await
                .agent_binding(&first.conversation),
            Some(instance_id),
            "conversation binding survives a fresh daemon catalog load"
        );
        drop(reopened);

        manager
            .load_availability(instance_id)
            .await
            .expect("load availability for safe error projection")
            .record_convergence_error(
                "service failed on port 54321 with PID 123 and private instance details".to_owned(),
            )
            .await
            .expect("record private convergence diagnostic");
        let failed_status = manager
            .agent_inspect_project(&first)
            .await
            .expect("inspect privacy-safe convergence failure");
        let projected_error = failed_status
            .availability
            .and_then(|availability| availability.last_error)
            .expect("project convergence error");
        assert_eq!(
            projected_error,
            "The last project convergence attempt failed; inspect the project logs for details."
        );
        assert!(!projected_error.contains("54321"));
        assert!(!projected_error.contains("PID 123"));

        manager
            .agent_ensure_project(&first, Some("/untrusted/replacement".to_owned()))
            .await
            .expect("renew the same agent owner");
        let second = test_agent_context(&project_path, "second private conversation");
        manager
            .agent_ensure_project(&second, Some("/another/seed".to_owned()))
            .await
            .expect("ensure an independent agent owner");
        let snapshot = manager
            .load_availability(instance_id)
            .await
            .expect("reload agent availability")
            .snapshot()
            .await
            .expect("read renewed agent availability");
        assert_eq!(
            snapshot.trusted_launch_path(),
            Some("/agent/bin:/usr/bin"),
            "agent context seeds PATH once and never replaces known-good launch context"
        );
        assert_eq!(
            snapshot
                .demands()
                .iter()
                .filter(|lease| lease.kind() == DemandKind::AgentConversation)
                .count(),
            2,
            "separate conversations retain independent demand owners"
        );

        let encoded = serde_json::to_value(&status).expect("serialize agent status");
        fn assert_safe_keys(value: &serde_json::Value) {
            match value {
                serde_json::Value::Object(object) => {
                    for (key, child) in object {
                        assert!(
                            ![
                                "pid",
                                "port",
                                "instance_id",
                                "project_instance_id",
                                "demand_id",
                                "activity_generation"
                            ]
                            .contains(&key.as_str()),
                            "agent projection exposes forbidden key `{key}`"
                        );
                        assert_safe_keys(child);
                    }
                }
                serde_json::Value::Array(items) => {
                    for item in items {
                        assert_safe_keys(item);
                    }
                }
                _ => {}
            }
        }
        assert_safe_keys(&encoded);
        let encoded = encoded.to_string();
        assert!(!encoded.contains("first private conversation"));
        assert!(encoded.contains("https://agent-ensure.localhost:8443"));

        let other_path = dir.path().join("other-agent-project");
        std::fs::create_dir(&other_path).expect("create conflicting project");
        std::fs::write(
            other_path.join("locald.toml"),
            "[project]\nname = \"other-agent-project\"\n",
        )
        .expect("write conflicting config");
        let conflicting = test_agent_context(&other_path, "first private conversation");
        let error = manager
            .agent_inspect_project(&conflicting)
            .await
            .expect_err("conversation cannot silently retarget");
        assert!(format!("{error:#}").contains("cannot silently retarget"));
    }

    #[tokio::test]
    async fn ensure_project_requires_successful_domain_host_synchronization() {
        let dir = tempdir().expect("create host-sync EnsureProject directory");
        let project_path = dir.path().join("host-sync-ensure-project");
        std::fs::create_dir(&project_path).expect("create host-sync project");
        std::fs::write(
            project_path.join("locald.toml"),
            r#"
[project]
name = "host-sync-ensure"
domain = "host-sync-ensure.test"

[services.web]
command = "unused-by-test-factory"
health_check = "true"

[services.web.env]
PATH = "/usr/bin:/bin"
"#,
        )
        .expect("write host-sync EnsureProject config");
        let mut manager = unregistered_availability_manager(dir.path());
        manager.set_host_syncer(Arc::new(ScriptedHostSyncer {
            calls: Arc::new(StdMutex::new(Vec::new())),
            failures: Arc::new(StdMutex::new(VecDeque::from([true, false]))),
        }));
        manager.set_https_port(Some(443)).await;
        manager.factories.insert(
            0,
            Arc::new(RetryingReadinessFactory {
                creates: Arc::new(AtomicUsize::new(1)),
                stops: Arc::new(AtomicUsize::new(0)),
            }),
        );

        let error = manager
            .ensure_project(project_path.clone(), DemandKey::manual_cli())
            .await
            .expect_err("host synchronization failure blocks Ready");
        let message = format!("{error:#}");
        assert!(
            message.contains("failed to apply the candidate complete hosts projection"),
            "unexpected EnsureProject error: {message}"
        );
        assert!(
            message.contains("injected scripted host synchronization failure"),
            "unexpected EnsureProject error: {message}"
        );

        assert!(
            manager
                .registry
                .lock()
                .await
                .get_project(&project_path)
                .is_none(),
            "failed host publication leaves project registration unpublished"
        );
        let catalog_path = manager.registry.lock().await.storage_path().to_path_buf();
        assert!(
            manager
                .catalog_publication_journal
                .load(&catalog_path)
                .await
                .expect("inspect aborted catalog publication journal")
                .is_none(),
            "durably restored hosts leave no active catalog publication"
        );
        assert!(
            manager
                .lifecycle_journal
                .load()
                .await
                .expect("inspect retryable lifecycle intent")
                .is_some(),
            "the outer lifecycle intent remains available for startup recovery"
        );
        assert!(
            manager.lifecycle_recovery_required.load(Ordering::Acquire),
            "no later lifecycle mutation is admitted before recovery"
        );
    }

    #[tokio::test]
    async fn background_convergence_bounds_readiness_before_visiting_later_projects() {
        let dir = tempdir().expect("create background convergence directory");
        let first_path = dir.path().join("first-project");
        let second_path = dir.path().join("second-project");
        std::fs::create_dir_all(&first_path).expect("create first project");
        std::fs::create_dir_all(&second_path).expect("create second project");

        let mut catalog = Registry::with_path(dir.path().join("catalog.json"));
        for path in [&first_path, &second_path] {
            let discovery = Registry::discover(
                std::fs::canonicalize(path).expect("canonical background project"),
            )
            .await
            .expect("discover background project");
            catalog
                .register_project(discovery, None)
                .expect("register background project");
        }
        catalog.save().await.expect("save background catalog");
        let ordered_instances = catalog
            .instances
            .iter()
            .map(|(instance_id, record)| {
                (
                    *instance_id,
                    record
                        .current_path
                        .clone()
                        .expect("background project remains present"),
                )
            })
            .collect::<Vec<_>>();
        let (slow_instance, slow_path) = &ordered_instances[0];
        let (later_instance, later_path) = &ordered_instances[1];

        for (path, name) in [
            (slow_path, "background-slow"),
            (later_path, "background-later"),
        ] {
            let health_check = if name == "background-slow" {
                "false"
            } else {
                "true"
            };
            std::fs::write(
                path.join("locald.toml"),
                format!(
                    r#"
[project]
name = "{name}"
domain = "{name}.localhost"

[services.web]
command = "unused-by-test-factory"
health_check = "{health_check}"

[services.web.env]
PATH = "/usr/bin:/bin"
"#
                ),
            )
            .expect("write background project config");
        }

        let availability_data_dir = dir.path().join("availability-data");
        for instance_id in [*slow_instance, *later_instance] {
            let mut availability = AvailabilityStore::load(&availability_data_dir, instance_id)
                .await
                .expect("load background availability");
            availability
                .ensure_demand(DemandKey::manual_cli())
                .await
                .expect("demand background project");
        }

        let mut manager = ProcessManager::new_with_availability_data_dir(
            dir.path().join("notify.sock"),
            Arc::new(StateManager::with_path(dir.path().join("state.json"))),
            Arc::new(Mutex::new(catalog)),
            Arc::new(Mutex::new(AttachmentStore::new(
                dir.path().join("attachments.json"),
            ))),
            None,
            availability_data_dir.clone(),
        )
        .expect("create background convergence manager");
        manager.set_host_syncer(Arc::new(NoopHostSyncer));
        let creates = Arc::new(AtomicUsize::new(0));
        let readiness_observed = Arc::new(tokio::sync::Notify::new());
        manager.set_readiness_wait_hook(readiness_observed.clone());
        manager.factories.insert(
            0,
            Arc::new(RetryingReadinessFactory {
                creates: creates.clone(),
                stops: Arc::new(AtomicUsize::new(0)),
            }),
        );
        for (instance_id, path) in &ordered_instances {
            assert!(
                manager
                    .availability_is_managed(*instance_id)
                    .await
                    .expect("classify background availability")
            );
            assert!(
                manager.path_matches_instance(path, *instance_id).await,
                "background catalog identity resolves before convergence"
            );
        }
        let sweep = tokio::spawn({
            let manager = manager.clone();
            async move { manager.converge_all_project_availability().await }
        });
        let readiness_observed =
            tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, readiness_observed.notified())
                .await;
        assert!(
            readiness_observed.is_ok(),
            "the first background project enters its readiness wait; creates={}, sweep_finished={}",
            creates.load(Ordering::SeqCst),
            sweep.is_finished()
        );
        assert_eq!(
            *manager
                .readiness_wait_timeout
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner),
            Some(BACKGROUND_SERVICE_READINESS_TIMEOUT)
        );
        assert_eq!(creates.load(Ordering::SeqCst), 1);
        assert_eq!(
            manager
                .services
                .lock()
                .await
                .get_display("background-slow:web")
                .expect("test service")
                .health_status,
            HealthStatus::Starting
        );
        tokio::time::pause();

        tokio::time::advance(
            BACKGROUND_SERVICE_READINESS_TIMEOUT
                .checked_sub(Duration::from_millis(1))
                .expect("background readiness exceeds one millisecond"),
        )
        .await;
        assert!(!sweep.is_finished());
        assert_eq!(
            creates.load(Ordering::SeqCst),
            1,
            "later projects wait only for the bounded background deadline"
        );

        tokio::time::advance(Duration::from_millis(1)).await;
        tokio::time::resume();
        tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, async {
            loop {
                if creates.load(Ordering::SeqCst) == 2 {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("the sweep visits the later project at the background deadline");
        tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, sweep)
            .await
            .expect("the sweep completes after visiting the later project")
            .expect("background convergence task joins");

        assert_eq!(creates.load(Ordering::SeqCst), 2);
        assert_eq!(
            manager
                .services
                .lock()
                .await
                .get_display("background-slow:web")
                .expect("test service")
                .health_status,
            HealthStatus::Starting,
            "the slow owned runtime remains eligible to finish"
        );
        let slow_port = {
            let services = manager.services.lock().await;
            let service = &services
                .get_display("background-slow:web")
                .expect("test service");
            assert!(
                service.pending_port_guard.is_some(),
                "the unbound cold build retains its allocator reservation"
            );
            service
                .sticky_port
                .expect("the cold build retains its assigned endpoint")
        };
        assert!(
            manager
                .port_allocator
                .try_allocate_specific(slow_port)
                .is_none(),
            "the retained cold build's unbound port cannot be reallocated"
        );
        assert_eq!(
            manager
                .services
                .lock()
                .await
                .get_display("background-later:web")
                .expect("test service")
                .health_status,
            HealthStatus::Healthy,
            "the later project converges in the same sweep"
        );
        assert!(
            manager
                .services
                .lock()
                .await
                .get_display("background-later:web")
                .expect("test service")
                .pending_port_guard
                .is_none(),
            "a ready service releases its allocator reservation"
        );
        let slow_snapshot = AvailabilityStore::load(&availability_data_dir, *slow_instance)
            .await
            .expect("reload slow availability")
            .snapshot()
            .await
            .expect("read slow convergence result");
        assert!(
            slow_snapshot
                .last_convergence_error()
                .is_some_and(|message| message.contains("timed out after 30s"))
        );
        let later_snapshot = AvailabilityStore::load(&availability_data_dir, *later_instance)
            .await
            .expect("reload later availability")
            .snapshot()
            .await
            .expect("read later convergence result");
        assert_eq!(later_snapshot.last_convergence_error(), None);

        let slow_coordinator = manager.availability_coordinator(*slow_instance).await;
        let slow_foreground_guard = slow_coordinator.runtime.lock().await;
        let mut later_availability =
            AvailabilityStore::load(&availability_data_dir, *later_instance)
                .await
                .expect("reload later availability before pause");
        later_availability
            .pause_project()
            .await
            .expect("pause later project behind busy coordinator");

        let busy_sweep = tokio::spawn({
            let manager = manager.clone();
            async move { manager.converge_all_project_availability().await }
        });
        tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, busy_sweep)
            .await
            .expect("background sweep skips the foreground-owned coordinator")
            .expect("busy-coordinator sweep joins");
        assert!(
            manager
                .get_service_controller("background-later:web")
                .await
                .is_none(),
            "the sweep visits later projects while a prior coordinator is busy"
        );
        drop(slow_foreground_guard);

        let mut slow_availability = AvailabilityStore::load(&availability_data_dir, *slow_instance)
            .await
            .expect("reload slow availability before cleanup");
        slow_availability
            .pause_project()
            .await
            .expect("pause retained cold build");
        manager
            .converge_managed_instance(*slow_instance, None, false, false)
            .await
            .expect("stop retained cold build");
        assert!(
            manager
                .port_allocator
                .try_allocate_specific(slow_port)
                .is_some(),
            "stopping the retained runtime releases its allocator reservation"
        );
    }

    #[tokio::test]
    async fn concurrent_ensure_project_calls_share_one_runtime_transition() {
        let dir = tempdir().expect("create concurrent EnsureProject directory");
        let project_path = dir.path().join("concurrent-ensure-project");
        std::fs::create_dir(&project_path).expect("create concurrent EnsureProject project");
        write_availability_worker_config(
            &project_path,
            "concurrent-ensure",
            "concurrent-ensure.localhost",
            &["web"],
        );
        let mut manager = unregistered_availability_manager(dir.path());
        manager.set_http_port(Some(80)).await;
        manager.set_https_port(Some(443)).await;
        let publication_reached = Arc::new(tokio::sync::Notify::new());
        let resume_publication = Arc::new(tokio::sync::Notify::new());
        manager.set_config_publication_hook(ConfigPublicationHook {
            reached: publication_reached.clone(),
            resume: resume_publication.clone(),
        });
        let prepare_entered = Arc::new(tokio::sync::Notify::new());
        let release_prepare = Arc::new(tokio::sync::Notify::new());
        let start_count = Arc::new(AtomicUsize::new(0));
        manager.factories.insert(
            0,
            Arc::new(BlockingPrepareFactory {
                entered: prepare_entered.clone(),
                release: release_prepare.clone(),
                start_count: start_count.clone(),
                stop_count: Arc::new(AtomicUsize::new(0)),
            }),
        );

        let first = tokio::spawn({
            let manager = manager.clone();
            let project_path = project_path.clone();
            async move {
                manager
                    .ensure_project(project_path, DemandKey::manual_cli())
                    .await
            }
        });
        tokio::time::timeout(
            TEST_STARTUP_BOUNDARY_TIMEOUT,
            publication_reached.notified(),
        )
        .await
        .expect("first ensure reaches initial catalog publication");
        let second = tokio::spawn({
            let manager = manager.clone();
            let project_path = project_path.clone();
            async move {
                manager
                    .ensure_project(project_path, DemandKey::manual_cli())
                    .await
            }
        });
        tokio::task::yield_now().await;
        assert!(!second.is_finished());
        resume_publication.notify_one();
        tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, prepare_entered.notified())
            .await
            .expect("first ensure reaches service preparation");
        assert!(!second.is_finished());
        release_prepare.notify_one();

        let (first, second) = tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, async {
            tokio::join!(first, second)
        })
        .await
        .expect("concurrent ensures finish after readiness");
        let first = first
            .expect("join first ensure")
            .expect("first ensure succeeds");
        let second = second
            .expect("join second ensure")
            .expect("second ensure succeeds");
        assert_eq!(first.state, EnsureProjectState::Ready);
        assert_eq!(second.state, EnsureProjectState::Ready);
        assert_eq!(start_count.load(Ordering::SeqCst), 1);
        assert_eq!(manager.registry.lock().await.instances.len(), 1);
    }

    #[tokio::test]
    async fn paused_multi_service_ensure_is_projected_and_later_semantic_activity_resumes() {
        let dir = tempdir().expect("create superseded EnsureProject directory");
        let project_path = dir.path().join("superseded-ensure-project");
        let (mut manager, instance_id, availability_data_dir) =
            availability_manager(dir.path(), &project_path, "superseded-ensure").await;
        manager.set_http_port(Some(80)).await;
        manager.set_https_port(Some(443)).await;
        write_availability_worker_config(
            &project_path,
            "superseded-ensure",
            "superseded-ensure.localhost",
            &["web", "worker"],
        );
        let prepare_entered = Arc::new(tokio::sync::Notify::new());
        let release_prepare = Arc::new(tokio::sync::Notify::new());
        let start_count = Arc::new(AtomicUsize::new(0));
        let stop_count = Arc::new(AtomicUsize::new(0));
        manager.factories.insert(
            0,
            Arc::new(BlockingPrepareFactory {
                entered: prepare_entered.clone(),
                release: release_prepare.clone(),
                start_count: start_count.clone(),
                stop_count: stop_count.clone(),
            }),
        );

        let ensure = tokio::spawn({
            let manager = manager.clone();
            let project_path = project_path.clone();
            async move {
                manager
                    .ensure_project(project_path, DemandKey::manual_cli())
                    .await
            }
        });
        tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, prepare_entered.notified())
            .await
            .expect("multi-service ensure reaches its first service preparation");

        let (started_key, started_service, controller_generation) = {
            let services = manager.services.lock().await;
            let (key, service) = services
                .iter()
                .next()
                .expect("prepared service is published before its build blocks");
            (
                key.clone(),
                ProcessManager::service_display_name(key, service),
                service.controller_generation,
            )
        };
        manager
            .broadcast_log(
                started_key,
                controller_generation,
                LogEntry {
                    timestamp: 1,
                    service: started_service.clone(),
                    instance_id: None,
                    service_name: None,
                    service_domain: None,
                    stream: locald_core::ipc::LogStream::Stdout,
                    message: "build output retained across supersession".to_owned(),
                },
            )
            .await;

        let pause = tokio::spawn({
            let manager = manager.clone();
            let project_path = project_path.clone();
            async move { manager.project_pause_availability(&project_path).await }
        });
        let mut availability = AvailabilityStore::load(&availability_data_dir, instance_id)
            .await
            .expect("load superseded ensure availability");
        tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, async {
            loop {
                if availability
                    .snapshot()
                    .await
                    .expect("observe pause publication")
                    .is_paused()
                {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("pause becomes authoritative while prepare is blocked");
        release_prepare.notify_one();

        let error = tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, ensure)
            .await
            .expect("superseded ensure returns")
            .expect("superseded ensure task joins")
            .expect_err("pause prevents the in-flight ensure from reaching Ready");
        assert!(error.is::<AvailabilityStartSuperseded>());

        tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, pause)
            .await
            .expect("pause convergence completes")
            .expect("pause task joins")
            .expect("pause succeeds");
        assert_eq!(start_count.load(Ordering::SeqCst), 0);
        assert_eq!(stop_count.load(Ordering::SeqCst), 1);
        for service in ["web", "worker"] {
            assert!(
                manager
                    .get_service_controller(&format!("superseded-ensure:{service}"))
                    .await
                    .is_none(),
                "paused supersession leaves every required service stopped"
            );
        }
        assert!(
            manager
                .get_recent_logs_for_instance(Some(instance_id))
                .iter()
                .any(|entry| entry.message == "build output retained across supersession"),
            "service logs remain available after the superseded controller is stopped"
        );

        manager.factories.remove(0);
        manager.factories.insert(
            0,
            Arc::new(RetryPrepareFactory {
                failure_consumed: Arc::new(AtomicBool::new(true)),
                stop_count: Arc::new(AtomicUsize::new(0)),
            }),
        );
        let resumed = manager
            .ensure_project(project_path.clone(), DemandKey::manual_cli())
            .await
            .expect("later semantic activity starts a new generation and resumes");
        assert_eq!(resumed.state, EnsureProjectState::Ready);
        assert_eq!(resumed.services.len(), 2);
        assert!(
            !availability
                .snapshot()
                .await
                .expect("read resumed availability")
                .is_paused()
        );
        let projected = manager
            .ensure_project_superseded_result(&project_path, &error)
            .await
            .expect("project superseding lifecycle state")
            .expect("availability supersession is recognized");
        assert_eq!(projected.project_name.as_deref(), Some("superseded-ensure"));
        assert_eq!(
            projected.state,
            ProjectLifecycleState::Paused,
            "the first ensure reports the lifecycle snapshot that superseded it"
        );
        assert!(
            projected
                .reasons
                .iter()
                .any(|reason| reason.code == "paused"),
            "a later semantic resume cannot replace the first ensure's supersession reason"
        );

        manager
            .project_pause_availability(&project_path)
            .await
            .expect("clean up resumed project");
    }

    #[tokio::test]
    async fn ensure_project_surfaces_the_exact_readiness_timeout() {
        let dir = tempdir().expect("create timed EnsureProject directory");
        let project_path = dir.path().join("timed-ensure-project");
        let (mut manager, instance_id, availability_data_dir) =
            availability_manager(dir.path(), &project_path, "timed-ensure").await;
        manager.set_http_port(Some(80)).await;
        manager.set_https_port(Some(443)).await;
        std::fs::write(
            project_path.join("locald.toml"),
            r#"
[project]
name = "timed-ensure"
domain = "timed-ensure.localhost"

[services.web]
command = "unused-by-test-factory"
health_check = "false"

[services.web.env]
PATH = "/usr/bin:/bin"
"#,
        )
        .expect("write timed EnsureProject config");
        let creates = Arc::new(AtomicUsize::new(0));
        manager.factories.insert(
            0,
            Arc::new(RetryingReadinessFactory {
                creates: creates.clone(),
                stops: Arc::new(AtomicUsize::new(0)),
            }),
        );

        let ensure = tokio::spawn({
            let manager = manager.clone();
            let project_path = project_path.clone();
            async move {
                manager
                    .ensure_project(project_path, DemandKey::manual_cli())
                    .await
            }
        });
        tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, async {
            loop {
                if creates.load(Ordering::SeqCst) == 1
                    && manager
                        .services
                        .lock()
                        .await
                        .get_display("timed-ensure:web")
                        .is_some_and(|service| service.health_status == HealthStatus::Starting)
                {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("EnsureProject reaches readiness polling");
        tokio::time::pause();
        let former_deadline = Duration::from_secs(30);
        tokio::time::advance(former_deadline).await;
        assert!(
            !ensure.is_finished(),
            "a normal cold build may continue beyond the former 30-second deadline"
        );
        tokio::time::advance(
            SERVICE_READINESS_TIMEOUT
                .checked_sub(former_deadline)
                .expect("service readiness exceeds the former deadline"),
        )
        .await;
        let error = ensure
            .await
            .expect("join timed EnsureProject")
            .expect_err("unbound assigned endpoint times out");
        assert!(format!("{error:#}").contains("timed out after 300s"));
        assert!(
            manager
                .ensure_project_superseded_result(&project_path, &error)
                .await
                .expect("classify readiness failure")
                .is_none(),
            "a genuine readiness failure remains distinct from lifecycle supersession"
        );

        let mut availability = AvailabilityStore::load(&availability_data_dir, instance_id)
            .await
            .expect("load timed EnsureProject availability");
        assert!(
            availability
                .desired_up()
                .await
                .expect("timed EnsureProject remains desired up")
        );
        assert!(
            availability
                .snapshot()
                .await
                .expect("read timed EnsureProject failure")
                .last_convergence_error()
                .is_some_and(|message| message.contains("timed out after 300s"))
        );
        assert_eq!(
            manager
                .services
                .lock()
                .await
                .get_display("timed-ensure:web")
                .expect("test service")
                .health_status,
            HealthStatus::Starting,
            "a live owned runtime remains eligible to finish after the caller's deadline"
        );
    }

    #[tokio::test]
    async fn readiness_timeout_preserves_demand_and_retry_clears_the_convergence_error() {
        let dir = tempdir().expect("create retry readiness directory");
        let project_path = dir.path().join("retry-readiness-project");
        let readiness_marker = dir.path().join("retry-readiness-ready");
        let clock = FakeAvailabilityClock::new(TEST_AVAILABILITY_START_SECONDS);
        let (mut manager, instance_id, _availability_data_dir) = availability_manager_with_clock(
            dir.path(),
            &project_path,
            "retry-readiness",
            SharedAvailabilityClock::new(clock.clone()),
        )
        .await;
        tokio::fs::write(
            project_path.join("locald.toml"),
            format!(
                r#"
[project]
name = "retry-readiness"
domain = "retry-readiness.localhost"

[services.db]
command = "ignored by readiness fixture"
health_check = "test -f {readiness_marker}"

[services.db.env]
PATH = "/usr/bin:/bin"

[services.web]
command = "ignored by readiness fixture"
depends_on = ["db"]
health_check = "test -f {readiness_marker}"

[services.web.env]
PATH = "/usr/bin:/bin"
"#,
                readiness_marker = readiness_marker.display()
            ),
        )
        .await
        .expect("write retry readiness config");
        let creates = Arc::new(AtomicUsize::new(0));
        let stops = Arc::new(AtomicUsize::new(0));
        manager.factories.insert(
            0,
            Arc::new(RetryingReadinessFactory {
                creates: creates.clone(),
                stops: stops.clone(),
            }),
        );

        let first_ensure = tokio::spawn({
            let manager = manager.clone();
            let project_path = project_path.clone();
            async move {
                manager
                    .project_ensure_availability(&project_path, DemandKey::manual_cli())
                    .await
            }
        });
        tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, async {
            loop {
                if creates.load(Ordering::SeqCst) == 1
                    && manager
                        .services
                        .lock()
                        .await
                        .get_display("retry-readiness:db")
                        .is_some_and(|service| service.health_status == HealthStatus::Starting)
                {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("first ensure reaches its readiness wait");
        assert!(
            !first_ensure.is_finished(),
            "first ensure remains blocked on readiness after creating its controller"
        );
        assert_eq!(creates.load(Ordering::SeqCst), 1);
        assert!(
            manager
                .get_service_controller("retry-readiness:web")
                .await
                .is_none(),
            "dependent service cannot start before its dependency is ready"
        );
        tokio::task::yield_now().await;

        tokio::time::pause();
        tokio::time::advance(SERVICE_READINESS_TIMEOUT).await;
        let error = first_ensure
            .await
            .expect("first ensure task joins")
            .expect_err("first controller never satisfies its readiness probe");
        assert!(format!("{error:#}").contains("timed out after 300s"));

        let mut availability = manager
            .load_availability(instance_id)
            .await
            .expect("load readiness availability after timeout");
        let failed = availability
            .snapshot()
            .await
            .expect("read failed readiness state");
        assert!(
            availability
                .desired_up()
                .await
                .expect("failed readiness remains desired up")
        );
        assert!(!failed.demands().is_empty());
        assert!(
            failed
                .last_convergence_error()
                .is_some_and(|message| message.contains("timed out after 300s"))
        );
        assert_eq!(
            manager
                .services
                .lock()
                .await
                .get_display("retry-readiness:db")
                .expect("test service")
                .health_status,
            HealthStatus::Starting
        );

        assert!(
            manager
                .services
                .lock()
                .await
                .get_display("retry-readiness:db")
                .expect("test service")
                .sticky_port
                .is_some(),
            "timed-out endpoint retains its assigned port"
        );
        tokio::fs::write(&readiness_marker, b"ready")
            .await
            .expect("make the original owned runtime ready");
        clock.advance(Duration::from_secs(30));
        let retry = tokio::spawn({
            let manager = manager.clone();
            let project_path = project_path.clone();
            async move { manager.converge_project_availability(&project_path).await }
        });
        tokio::time::resume();
        tokio::time::timeout(TEST_STARTUP_BOUNDARY_TIMEOUT, retry)
            .await
            .expect("readiness retry completes after the configured probe becomes true")
            .expect("retry readiness task joins")
            .expect("automatic retry waits for the original runtime and becomes ready")
            .expect("project remains availability-managed");
        assert_eq!(
            creates.load(Ordering::SeqCst),
            2,
            "retry preserves the first controller and only creates its dependent"
        );
        assert_eq!(
            stops.load(Ordering::SeqCst),
            0,
            "retry does not erase progress by stopping the original controller"
        );
        assert!(manager.project_runtime_is_ready(instance_id).await);
        assert_eq!(
            availability
                .snapshot()
                .await
                .expect("read successful readiness retry")
                .last_convergence_error(),
            None
        );

        manager
            .project_pause_availability(&project_path)
            .await
            .expect("clean up retry readiness runtime");
    }

    #[tokio::test]
